/**
 * Exercise real original corpus edits, lifecycle consistency and hostile catalog boundaries.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - function required: line 28
 * - variable original: line 33
 * @@SYMBOL_INDEX_END
 */

import { beforeAll, describe, expect, it } from "vitest";
import { PRODUCTS } from "../../src/data/products";
import { compareTopics } from "../../src/lib/comparison";
import { toSearchDocument } from "../../src/lib/content";
import { answerQuestion, createSearchIndex, search } from "../../src/lib/search";
import {
  applyProduct,
  applyTopic,
  applyVersion,
  canonicalCatalog,
  MAX_CATALOG_BYTES,
  parseCatalogJson,
  removeTopic,
  validateCatalog,
  type KnowledgeCatalog,
} from "../../src/lib/workspace";
import { loadTopics } from "../../tools/load-topics";

function required<T>(value: T | undefined): T {
  if (value === undefined) throw new Error("Original fixture entry is required.");
  return value;
}

let original: KnowledgeCatalog;

beforeAll(async () => {
  original = validateCatalog({ schemaVersion: 1, products: PRODUCTS, topics: await loadTopics() });
});

describe("actual catalog workflows", () => {
  it("round trips the complete original corpus without changing authored arrays or supplied provenance", () => {
    const result = validateCatalog(parseCatalogJson(canonicalCatalog(original)));
    expect(result).toEqual(original);
    expect(result.topics).toHaveLength(12);
    expect(result.products).toHaveLength(2);
    expect(result.topics[0]).not.toBe(original.topics[0]);
  });

  it("uses original search and extractive abstention on a real edited edition", () => {
    const index = createSearchIndex(original.topics.map(toSearchDocument));
    const result = search(index, "E-104", { productId: "apex-control-hub", version: "2.0" });
    expect(result[0]?.document.id).toBe("apex-2-0-e104");
    expect(answerQuestion(index, "unrelated fictional zephyr penguin", {})).toMatchObject({
      status: "abstained",
      citations: [],
    });
  });

  it("clones an explicit new current edition and retains old content, warnings and source claims", () => {
    const before = canonicalCatalog(original);
    const catalog = applyVersion(
      original,
      "apex-control-hub",
      { version: "2.1", lifecycle: "current", released: "2026-11-11" },
      "2.0",
    );
    expect(canonicalCatalog(original)).toBe(before);
    const old = catalog.topics.find((item) => item.id === "apex-2-0-e104");
    const created = catalog.topics.find((item) => item.id === "apex-2-0-e104-2-1");
    expect(old?.lifecycle).toBe("maintained");
    expect(created?.lifecycle).toBe("current");
    expect(created?.sections).toEqual(old?.sections);
    expect(created?.provenance).toEqual(old?.provenance);
    expect(catalog.topics.find((item) => item.id === "apex-1-5-e104")).toEqual(
      original.topics.find((item) => item.id === "apex-1-5-e104"),
    );
    const comparison = compareTopics(catalog.topics, catalog.products, {
      productId: "apex-control-hub",
      from: "2.0",
      to: "2.1",
      slug: "error-e-104",
    });
    expect(comparison.sections.map((section) => section.warningStatus)).toEqual([
      "unchanged",
      "none",
    ]);
    expect(comparison.fromVersion.lifecycle).toBe("maintained");
    expect(comparison.toVersion.lifecycle).toBe("current");
  });

  it("keeps complete warning changes visible through the original comparison engine", () => {
    const catalog = structuredClone(original);
    const topic = required(
      structuredClone(catalog.topics.find((item) => item.id === "apex-2-0-e104")),
    );
    const changed = {
      ...topic,
      sections: topic.sections.map((section) =>
        section.warning
          ? {
              ...section,
              warning: {
                ...section.warning,
                avoidance: "Use the approved replacement and retain the event evidence.",
              },
            }
          : section,
      ),
    };
    const result = applyTopic(catalog, JSON.stringify(changed), topic.id);
    expect(
      result.topics.find((item) => item.id === topic.id)?.sections[0]?.warning?.avoidance,
    ).toBe("Use the approved replacement and retain the event evidence.");
    expect(catalog).toEqual(original);
    const without = removeTopic(result, topic.id);
    const comparison = compareTopics(without.topics, without.products, {
      productId: "apex-control-hub",
      from: "1.5",
      to: "2.0",
      slug: "error-e-104",
    });
    expect(comparison.after).toBeUndefined();
    expect(comparison.sections.every((section) => section.status === "absent")).toBe(true);
  });

  it("adds a new topic only through Add and edits stable identities explicitly", () => {
    const topic = { ...required(original.topics[0]), id: "new-topic", topicSlug: "new-topic" };
    const created = applyTopic(original, JSON.stringify(topic));
    expect(created.topics).toHaveLength(13);
    expect(() => applyTopic(created, JSON.stringify(topic))).toThrow("Choose Edit");
    expect(() =>
      applyTopic(original, JSON.stringify(topic), required(original.topics[0]).id),
    ).toThrow("Choose Add");
    expect(() => applyTopic(original, JSON.stringify(topic), "not-known")).toThrow("Choose Add");
    expect(() => removeTopic(original, "not-known")).toThrow("Select a known topic");
  });

  it("retains archived topics when an edition is retired and refuses inconsistent direct product edits", () => {
    const result = applyVersion(original, "apex-control-hub", {
      version: "2.0",
      lifecycle: "retired",
      released: "2026-03-12",
      endOfSupport: "2027-03-12",
    });
    expect(
      result.topics
        .filter((item) => item.productId === "apex-control-hub" && item.version === "2.0")
        .every((item) => item.lifecycle === "retired"),
    ).toBe(true);
    expect(result.topics).toHaveLength(12);
    expect(() =>
      applyProduct(
        original,
        JSON.stringify({ ...original.products[0], versions: [] }),
        required(original.products[0]).id,
      ),
    ).toThrow("applicability");
  });

  it("adds an empty future product and synchronizes an explicitly edited name", () => {
    const product = {
      id: "new-product",
      name: "New Product",
      description: "A locally authored future product.",
      versions: [],
    };
    expect(applyProduct(original, JSON.stringify(product)).products).toHaveLength(3);
    const changed = { ...original.products[0], name: "Renamed Example Product" };
    const catalog = applyProduct(original, JSON.stringify(changed), changed.id);
    expect(
      catalog.topics
        .filter((topic) => topic.productId === changed.id)
        .every((topic) => topic.productName === changed.name),
    ).toBe(true);
    expect(() => applyProduct(original, JSON.stringify(changed))).toThrow("Choose Edit");
    expect(() => applyProduct(original, JSON.stringify(product), "not-known")).toThrow(
      "Choose Add",
    );
    expect(() => applyProduct(original, JSON.stringify(product), changed.id)).toThrow("Choose Add");
  });

  it.each(["unknown-product", "existing-clone", "unknown-clone"])(
    "rejects invalid edition command %s without partial mutation",
    (kind) => {
      const before = canonicalCatalog(original);
      const version = {
        version: kind === "existing-clone" ? "2.0" : "2.1",
        lifecycle: "maintained",
        released: "2026-11-11",
      };
      expect(() =>
        applyVersion(
          original,
          kind === "unknown-product" ? "missing" : "apex-control-hub",
          version,
          kind === "unknown-clone" ? "8.0" : "2.0",
        ),
      ).toThrow();
      expect(canonicalCatalog(original)).toBe(before);
    },
  );
});

describe("closed import boundaries", () => {
  it.each([
    '{"key":1,"key":2}',
    '{"key":1,"\\u006bey":2}',
    '{"outer":{"name":"first","name":"second"}}',
  ])("rejects actual duplicate JSON keys %s", (text) =>
    expect(() => parseCatalogJson(text)).toThrow("Duplicate"),
  );

  it("does not confuse quoted braces or repeated array values with object keys", () => {
    const value = { text: '{"key": "quoted"}', rows: ["same", "same", { text: "same" }] };
    expect(parseCatalogJson(JSON.stringify(value))).toEqual(value);
  });

  it("enforces actual UTF8 byte and nesting budgets before domain mutation", () => {
    expect(() => parseCatalogJson('"' + "界".repeat(MAX_CATALOG_BYTES / 2) + '"')).toThrow(
      "two MiB",
    );
    expect(() => parseCatalogJson("[".repeat(17) + "0" + "]".repeat(17))).toThrow("sixteen");
    expect(() => parseCatalogJson("{broken}")).toThrow();
    expect(() => parseCatalogJson('{"value":NaN}')).toThrow();
  });

  it.each([
    [
      "schema",
      (c: Record<string, unknown>) => {
        c["schemaVersion"] = true;
      },
    ],
    [
      "unknown-root",
      (c: Record<string, unknown>) => {
        c["hidden"] = "not admitted";
      },
    ],
    [
      "products-type",
      (c: Record<string, unknown>) => {
        c["products"] = {};
      },
    ],
    [
      "topics-type",
      (c: Record<string, unknown>) => {
        c["topics"] = null;
      },
    ],
  ])("rejects malformed root %s", (_name, mutate) => {
    const value = structuredClone(original) as unknown as Record<string, unknown>;
    mutate(value);
    expect(() => validateCatalog(value)).toThrow();
  });

  it.each([
    [
      "unknown-product-field",
      (p: Record<string, unknown>) => {
        p["hidden"] = true;
      },
    ],
    [
      "path-id",
      (p: Record<string, unknown>) => {
        p["id"] = "../outside";
      },
    ],
    [
      "empty-name",
      (p: Record<string, unknown>) => {
        p["name"] = " ";
      },
    ],
    [
      "long-description",
      (p: Record<string, unknown>) => {
        p["description"] = "x".repeat(401);
      },
    ],
    [
      "duplicate-version",
      (p: Record<string, unknown>) => {
        const a = p["versions"] as unknown[];
        a.push(a[0]);
      },
    ],
    [
      "two-current",
      (p: Record<string, unknown>) => {
        const a = p["versions"] as Record<string, unknown>[];
        required(a[1])["lifecycle"] = "current";
      },
    ],
    [
      "unknown-version-field",
      (p: Record<string, unknown>) => {
        required((p["versions"] as Record<string, unknown>[])[0])["extra"] = 1;
      },
    ],
    [
      "ambiguous-version",
      (p: Record<string, unknown>) => {
        required((p["versions"] as Record<string, unknown>[])[0])["version"] = "02.0";
      },
    ],
    [
      "invalid-date",
      (p: Record<string, unknown>) => {
        required((p["versions"] as Record<string, unknown>[])[0])["released"] = "2026-02-30";
      },
    ],
    [
      "unknown-lifecycle",
      (p: Record<string, unknown>) => {
        required((p["versions"] as Record<string, unknown>[])[0])["lifecycle"] = "hidden";
      },
    ],
    [
      "missing-retirement-date",
      (p: Record<string, unknown>) => {
        delete required((p["versions"] as Record<string, unknown>[])[2])["endOfSupport"];
      },
    ],
    [
      "reversed-support",
      (p: Record<string, unknown>) => {
        required((p["versions"] as Record<string, unknown>[])[2])["endOfSupport"] = "2000-01-01";
      },
    ],
  ])("rejects product contract violation %s", (_name, mutate) => {
    const value = structuredClone(original) as unknown as { products: Record<string, unknown>[] };
    mutate(required(value.products[0]));
    expect(() => validateCatalog(value)).toThrow();
  });

  it.each([
    [
      "unknown-field",
      (t: Record<string, unknown>) => {
        t["hidden"] = true;
      },
    ],
    [
      "invalid-title",
      (t: Record<string, unknown>) => {
        t["title"] = "x".repeat(91);
      },
    ],
    [
      "bad-text",
      (t: Record<string, unknown>) => {
        t["title"] = "bad\u0000text";
      },
    ],
    [
      "invalid-unicode",
      (t: Record<string, unknown>) => {
        t["title"] = "broken\ud800";
      },
    ],
    [
      "short-summary",
      (t: Record<string, unknown>) => {
        t["summary"] = "short";
      },
    ],
    [
      "unknown-product",
      (t: Record<string, unknown>) => {
        t["productId"] = "not-known";
      },
    ],
    [
      "wrong-name",
      (t: Record<string, unknown>) => {
        t["productName"] = "Not This Product";
      },
    ],
    [
      "unknown-version",
      (t: Record<string, unknown>) => {
        t["version"] = "99.0";
      },
    ],
    [
      "wrong-lifecycle",
      (t: Record<string, unknown>) => {
        t["lifecycle"] = t["lifecycle"] === "current" ? "retired" : "current";
      },
    ],
    [
      "invalid-date",
      (t: Record<string, unknown>) => {
        t["updated"] = "2026-11-31";
      },
    ],
    [
      "private-metadata",
      (t: Record<string, unknown>) => {
        t["visibility"] = "private";
      },
    ],
    [
      "unknown-type",
      (t: Record<string, unknown>) => {
        t["contentType"] = "executable";
      },
    ],
    [
      "bad-identifier",
      (t: Record<string, unknown>) => {
        t["identifiers"] = ["lower case"];
      },
    ],
    [
      "too-many-identifiers",
      (t: Record<string, unknown>) => {
        t["identifiers"] = Array(13).fill("E-100");
      },
    ],
    [
      "bad-synonym",
      (t: Record<string, unknown>) => {
        t["synonyms"] = ["x"];
      },
    ],
    [
      "bad-checksum",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["checksum"] = "A".repeat(64);
      },
    ],
    [
      "boolean-page",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["pages"] = [true];
      },
    ],
    [
      "duplicate-page",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["pages"] = [1, 1];
      },
    ],
    [
      "negative-page",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["pages"] = [0];
      },
    ],
    [
      "fraction-page",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["pages"] = [1.5];
      },
    ],
    [
      "huge-page",
      (t: Record<string, unknown>) => {
        (t["provenance"] as Record<string, unknown>)["pages"] = [1_000_001];
      },
    ],
    [
      "empty-sections",
      (t: Record<string, unknown>) => {
        t["sections"] = [];
      },
    ],
    [
      "duplicate-section",
      (t: Record<string, unknown>) => {
        const s = t["sections"] as unknown[];
        s.push(s[0]);
      },
    ],
    [
      "empty-paragraphs",
      (t: Record<string, unknown>) => {
        required((t["sections"] as Record<string, unknown>[])[0])["paragraphs"] = [];
      },
    ],
    [
      "empty-steps",
      (t: Record<string, unknown>) => {
        required((t["sections"] as Record<string, unknown>[])[0])["steps"] = [];
      },
    ],
    [
      "empty-code",
      (t: Record<string, unknown>) => {
        required((t["sections"] as Record<string, unknown>[])[0])["code"] = "";
      },
    ],
    [
      "partial-warning",
      (t: Record<string, unknown>) => {
        required((t["sections"] as Record<string, unknown>[])[0])["warning"] = {
          level: "danger",
          condition: "A condition",
        };
      },
    ],
    [
      "unknown-severity",
      (t: Record<string, unknown>) => {
        required((t["sections"] as Record<string, unknown>[])[0])["warning"] = {
          level: "critical",
          condition: "A condition",
          consequence: "A consequence",
          avoidance: "An avoidance",
        };
      },
    ],
  ])(
    "rejects topic boundary violation %s without altering the existing catalog",
    (_name, mutate) => {
      const value = structuredClone(original) as unknown as { topics: Record<string, unknown>[] };
      mutate(required(value.topics[0]));
      expect(() => validateCatalog(value)).toThrow();
    },
  );

  it("rejects duplicate stable IDs and canonical routes independently", () => {
    expect(() =>
      validateCatalog({
        ...original,
        products: [...original.products, original.products[0]],
      }),
    ).toThrow("Duplicate product identity");
    expect(() =>
      validateCatalog({ ...original, topics: [...original.topics, original.topics[0]] }),
    ).toThrow("Duplicate topic identity");
    expect(() =>
      validateCatalog({
        ...original,
        topics: [...original.topics, { ...original.topics[0], id: "distinct-id" }],
      }),
    ).toThrow("Duplicate canonical");
  });

  it("supports an explicit empty future catalog while refusing invalid root objects and excessive corpora", () => {
    expect(validateCatalog({ schemaVersion: 1, products: [], topics: [] })).toEqual({
      schemaVersion: 1,
      products: [],
      topics: [],
    });
    for (const value of [null, [], "not an object", Object.create({ hidden: true })])
      expect(() => validateCatalog(value)).toThrow();
    expect(() =>
      validateCatalog({
        ...original,
        products: Array.from({ length: 17 }, (_, i) => ({
          ...original.products[0],
          id: `product-${i}`,
        })),
      }),
    ).toThrow("item budget");
    expect(() =>
      validateCatalog({
        ...original,
        topics: Array.from({ length: 257 }, (_, i) => ({
          ...original.topics[0],
          id: `topic-${i}`,
          topicSlug: `topic-${i}`,
        })),
      }),
    ).toThrow("item budget");
  });

  it("refuses sparse or decorated IPC arrays rather than skipping their missing members", () => {
    expect(() => validateCatalog({ schemaVersion: 1, products: new Array(1), topics: [] })).toThrow(
      "item budget",
    );
    const products = [...original.products] as unknown as Record<string, unknown>;
    products["extra"] = "unknown array property";
    expect(() => validateCatalog({ ...original, products })).toThrow("item budget");
    const value = { ...original, [Symbol("unknown")]: "not JSON" };
    expect(() => validateCatalog(value)).toThrow("unknown object");
    const symbolArray = [...original.products];
    Object.defineProperty(symbolArray, Symbol("hidden"), { value: "not JSON" });
    expect(() => validateCatalog({ ...original, products: symbolArray })).toThrow("item budget");
  });

  it("refuses an otherwise valid catalog whose complete edition chooser exceeds the original route budget", () => {
    const product = required(original.products[0]);
    const template = required(original.topics.find((item) => item.productId === product.id));
    const versions = Array.from({ length: 12 }, (_, index) => ({
      version: `${index + 1}.0`,
      lifecycle: "maintained" as const,
      released: "2026-11-11",
    }));
    const topics = versions.flatMap((version) =>
      Array.from({ length: 9 }, (_, index) => ({
        ...template,
        id: `topic-${version.version.replace(".", "-")}-${index}`,
        topicSlug: `topic-${index}`,
        version: version.version,
        lifecycle: version.lifecycle,
      })),
    );
    expect(() =>
      validateCatalog({ schemaVersion: 1, products: [{ ...product, versions }], topics }),
    ).toThrow("comparison route budget");
    expect(
      validateCatalog({
        schemaVersion: 1,
        products: [{ ...product, versions }],
        topics: topics.filter((item) => !["topic-8", "topic-7"].includes(item.topicSlug)),
      }).topics,
    ).toHaveLength(84);
  });

  it("applies the complete catalog byte cap to object input as well as textual imports", () => {
    const topic = required(original.topics[0]);
    const sections = Array.from({ length: 5 }, (_, index) => ({
      id: `section-${index}`,
      title: "Bounded paragraph series",
      paragraphs: Array(64).fill("x".repeat(7000)),
    }));
    expect(() => validateCatalog({ ...original, topics: [{ ...topic, sections }] })).toThrow(
      "two MiB",
    );
  });
});
